(function(){const t=12,n=240,r=160;let a=0,o=0;const e=new Float32Array(t),i=new Float32Array(t),l=new Float32Array(t),s=new Float32Array(t);function c(h,t,a){"ram";const o=t-n,e=a-r;h.drawLine(n,r,n+o,r+e),h.drawLine(n,r,n-o,r+e),h.drawLine(n,r,n+o,r-e),h.drawLine(n,r,n-o,r-e)}return{init:function(n){a=n,o=0;for(let n=0;n<t;n++)e[n]=Math.randInt(628)/100,i[n]=(Math.randInt(20)+10)/1e3*(n%2?1:-1)},draw:function(h){"ram";if(h.setColor(3),o>0){h.setColor(0);for(let n=0;n<t;n++)c(h,0|l[n],0|s[n]);h.setColor(3)}const f=50+200*Math.abs(Math.sin(o/(40-6*a)));for(let o=0;o<t;o++)e[o]+=i[o]*(1+.7*a),l[o]=n+f*Math.cos(e[o]*(1+o%3*.2)),s[o]=r+f*Math.sin(e[o]*(1+o%2*.3));for(let n=0;n<t;n++)c(h,0|l[n],0|s[n]);o++}}});